def calculate_monoisotopic_mass(sequence, ncAA_dict):
# Calculate monoisotopic mass of peptide with ncAAs
mass = 0
for aa in sequence:
if aa in ncAA_dict:
mass += ncAA_dict[aa]['monoisotopic_mass']
else:
mass += standard_aa_mw[aa]
return mass
